{
  "lesson_summary": "Today's lesson plans to teach children to identify and count numbers from 0 to 9. It will focus on showing these numbers in various forms, such as objects, drawings, and fingers, and matching them to their corresponding numerals. The lesson uses examples like chalk dots, raised fingers, petals, tree branches, and stem leaves to illustrate these concepts.",
  "lesson_summary_short": "Today's lesson plans to teach identifying and counting numbers 0-9, using examples like chalk dots.",
  "checks_summary": "This quiz checks whether the class can identify and count numbers from 0 to 9, and match numerals to quantities shown in different forms.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Which of these is the numeral for seven?",
      "options": [
        "7",
        "5",
        "2"
      ],
      "correct_index": 0,
      "explanation": "The numeral '7' represents the quantity of seven, as shown with the chalk dots example in class.",
      "selected_because": "The lesson's worked example for counting chalk dots ended with writing the numeral 7.",
      "distractor_misconceptions": {
        "1": "Confuses seven with five",
        "2": "Confuses seven with two"
      },
      "option_feedback": {
        "correct": "Yes, '7' is the numeral for seven. Just like when we counted seven chalk dots and wrote '7' on the board.",
        "wrong": {
          "1": "This is the numeral for five. Remember, after counting seven chalk dots, we wrote the numeral '7'.",
          "2": "This is the numeral for two. When we counted seven chalk dots, the numeral we wrote was '7'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "The last count word is seven. Write the numeral: 7"
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "How many chalk dots are there?",
      "options": [
        "7",
        "5",
        "9"
      ],
      "correct_index": 0,
      "explanation": "Counting each dot one by one shows there are seven chalk dots.",
      "selected_because": "The worked example in the lesson was counting seven chalk dots.",
      "distractor_misconceptions": {
        "1": "Counts incorrectly, arriving at five",
        "2": "Counts incorrectly, arriving at nine"
      },
      "option_feedback": {
        "correct": "That's right! There are 7 chalk dots. We counted them one by one in class.",
        "wrong": {
          "1": "Let's count them again carefully. Remember to point to each dot once. There are 7 chalk dots.",
          "2": "Try counting each dot again, making sure not to skip any or count any twice. There are 7 chalk dots."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 7
      },
      "figure_role": "read_off",
      "source_quote": "How many chalk dots on the board? Point once to each dot in order Say one to seven, one word per dot"
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which hand shows two fingers?",
      "options": [
        "P",
        "Q",
        "R"
      ],
      "correct_index": 1,
      "explanation": "The hand labeled 'Q' clearly shows two raised fingers.",
      "selected_because": "The class practiced matching hands with different numbers of raised fingers to numerals.",
      "distractor_misconceptions": {
        "0": "Confuses two fingers with zero fingers",
        "2": "Confuses two fingers with one finger"
      },
      "option_feedback": {
        "correct": "You got it! Hand Q shows two fingers, just like we practiced in class.",
        "wrong": {
          "0": "Hand P shows an open hand, which means zero fingers. Hand Q shows two fingers.",
          "2": "Hand R shows one finger. Remember, hand Q shows two fingers."
        }
      },
      "figure": {
        "type": "count_objects",
        "rows": [
          {
            "picto": "hand",
            "count": 0,
            "label": "P"
          },
          {
            "picto": "hand",
            "count": 2,
            "label": "Q"
          },
          {
            "picto": "hand",
            "count": 1,
            "label": "R"
          }
        ]
      },
      "figure_role": "read_off",
      "source_quote": "Match each hand to its numeral: open hand, two raised fingers, one raised finger."
    },
    {
      "slo_id": "S4",
      "level": "apply",
      "question": "What numeral matches these petals?",
      "options": [
        "5",
        "6",
        "7"
      ],
      "correct_index": 0,
      "explanation": "Counting each petal one by one reveals there are five petals.",
      "selected_because": "The class observed and counted petals at the bottom of a picture.",
      "distractor_misconceptions": {
        "1": "Counts incorrectly, arriving at six",
        "2": "Counts incorrectly, arriving at seven"
      },
      "option_feedback": {
        "correct": "Excellent! There are 5 petals. You correctly counted each one.",
        "wrong": {
          "1": "Let's count the petals again carefully. Make sure to touch each petal as you count. There are 5 petals.",
          "2": "Remember to count each petal only once. If you count again, you will find there are 5 petals."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "flower",
        "count": 5
      },
      "figure_role": "read_off",
      "source_quote": "Observe the petals at the bottom of. Point to each once, count, and write the numeral."
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which of these shows the number five?",
      "options": [
        "A hand with five fingers",
        "A drawing of two trees",
        "The numeral '3'"
      ],
      "correct_index": 0,
      "explanation": "A hand with five raised fingers directly represents the quantity of five.",
      "selected_because": "The lesson taught showing numbers with fingers and drawings.",
      "distractor_misconceptions": {
        "1": "Confuses quantity with drawing size",
        "2": "Confuses numeral with quantity"
      },
      "option_feedback": {
        "correct": "That's right! A hand with five fingers clearly shows the number five.",
        "wrong": {
          "1": "A drawing of two trees shows the number two, no matter how big the trees are. Remember, we count the parts, not the size of the drawing.",
          "2": "The numeral '3' represents the number three. We are looking for something that shows the number five."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Show numbers 0 to 9 in different forms — objects, drawings, fingers — and match numerals."
    },
    {
      "slo_id": "S4",
      "level": "understand",
      "question": "What numeral matches these leaves?",
      "options": [
        "4",
        "3",
        "5"
      ],
      "correct_index": 1,
      "explanation": "Counting each leaf one by one shows there are three leaves.",
      "selected_because": "The class practiced counting stem leaves.",
      "distractor_misconceptions": {
        "0": "Counts incorrectly, arriving at four",
        "2": "Counts incorrectly, arriving at five"
      },
      "option_feedback": {
        "correct": "Correct! There are 3 leaves. You counted them perfectly.",
        "wrong": {
          "0": "Let's count the leaves again. Make sure to count each one only once. There are 3 leaves.",
          "2": "Count the leaves carefully. Remember, the numeral we write is the last count word we said. There are 3 leaves."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "leaf",
        "count": 3
      },
      "figure_role": "read_off",
      "source_quote": "Choose the tree branches or the stem leaves. Draw them, count once each, write the numeral."
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which is the correct way to count?",
      "options": [
        "One count word for each object",
        "Count the biggest objects first",
        "Guess the number by looking"
      ],
      "correct_index": 0,
      "explanation": "To count accurately, each object must be assigned exactly one count word.",
      "selected_because": "The lesson emphasized the rule of one count word per object.",
      "distractor_misconceptions": {
        "1": "Believes size affects counting order",
        "2": "Relies on visual estimation instead of counting"
      },
      "option_feedback": {
        "correct": "Yes, that's the correct way! One count word for each object, as we learned in class.",
        "wrong": {
          "1": "Remember, the size of an object does not change its count. We count each object equally, no matter its size.",
          "2": "Guessing can lead to mistakes. We learned to count each object carefully, one by one, to find the correct number."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "One count word for each object — never skip one or count one twice."
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Which of these is a numeral?",
      "options": [
        "4",
        "Tree",
        "Hand"
      ],
      "correct_index": 0,
      "explanation": "A numeral is a symbol used to represent a number, such as '4'.",
      "selected_because": "The lesson defined what a numeral is and matched them to quantities.",
      "distractor_misconceptions": {
        "1": "Confuses an object with a numeral",
        "2": "Confuses a body part with a numeral"
      },
      "option_feedback": {
        "correct": "That's right! '4' is a numeral, a symbol we use to write numbers.",
        "wrong": {
          "1": "A tree is an object, not a numeral. Remember, numerals are symbols like '4'.",
          "2": "A hand is a body part, not a numeral. Numerals are the written symbols for numbers, like '4'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "A number can be shown with objects, a drawing, fingers or a numeral."
    }
  ]
}
